function setup() {
  createCanvas(400, 400, WEBGL);
  brush.scaleBrushes(2);
  noLoop();
}

function draw() {
  translate(-width / 2, -height / 2);
  background("#f4efe4");

  // Sky
  brush.fill("#87CEEB"); // Sky blue
  brush.fillBleed(0.5); // Slight bleed for soft edges
  brush.beginShape();

  for (let i = 0; i < 100; i++) {
    let x = sin(i * 0.05) * 200;
    let y = cos(i * 0.05) * 200;
    brush.vertex(x, y);
  }

  brush.endShape(true);

  // Green hills
  brush.fill("#006400"); // Green hills
  brush.fillBleed(0.3); // Slight bleed for soft edges
  brush.beginShape();

  for (let i = 0; i < 100; i++) {
    let x = sin(i * 0.05) * 250;
    let y = cos(i * 0.05) * 250;
    brush.vertex(x, y);
  }

  brush.endShape(true);

  // Sun
  brush.fill("#FFD700"); // Yellow sun
  brush.fillBleed(0.8); // Strong bleed for sun's glow
  brush.beginShape();

  for (let i = 0; i < 10; i++) {
