  brush.scaleBrushes(2);
  noLoop();
}

function draw() {
  translate(-width / 2, -height / 2);
  background("#f4efe4");

  // Sky
  brush.fill("#87CEEB"); // Sky blue
  brush.fillBleed(0.5);
  brush.beginShape();
  for (let i = 0; i < 100; i++) {
    let x = cos(i * 0.05) * 200;
    let y = sin(i * 0.05) * 200;
    brush.vertex(x, y);
  }
  brush.endShape(true);

  // Green hills
  brush.fill("#006400"); // Green
  brush.fillBleed(0.3);
  brush.beginShape();
  for (let i = 0; i < 100; i++) {
    let x = cos(i * 0.05) * 250;
    let y = sin(i * 0.05) * 250;
    brush.vertex(x, y);
  }
  brush.endShape(true);

  // Sun
  brush.fill("#FFD700"); // Golden yellow
  brush.fillBleed(0.8);
  brush.beginShape();
  for (let i = 0; i < 100; i++) {
    let x = cos(i * 0.05) * 150;
    let y = sin(i * 0.05) * 150;
    brush.vertex(x, y);
  }
  brush.endShape(true);
}

